query IdempotencyLookup(
  $merchant_uid: String!
  $operation: IdempotencyOperation!
  $idempotency_key: String!
) {
  idempotencyLookup(
    merchant_uid: $merchant_uid
    operation: $operation
    idempotency_key: $idempotency_key
  ) {
    merchant_uid
    operation
    idempotency_status
    transaction_id
    authorization_id
    locked_until
    expires_at
  }
}

